        {"kind": "log", "sql": "SELECT level, LEFT(message,200) msg, COUNT(*) n FROM abnormal_logs WHERE service_name='ts-travel-service' AND level='SEVERE' GROUP BY 1,2 ORDER BY n DESC LIMIT 5", "claim": "Travel-service logs SEVERE HttpClientErrorException 408 Request Timeout with intact train-data bodies from the basic call."}
