    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, attr_span_kind, attr_http_response_status_code code, COUNT(*) n FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' GROUP BY ALL", "claim": "Ui-dashboard's server spans return 500 on 10 requests, and travel-plan 504s propagate to the user-facing tier."}]},
